// hooks/useTelegramWebApp.ts
import { useEffect, useState } from 'react';

export function getTelegramWebApp(): TelegramWebApp | null {
  return typeof window !== 'undefined' && window.Telegram ? window.Telegram.WebApp : null;
}

export function useTelegramWebApp() {
  const webApp = getTelegramWebApp();
  const [themeParams, setThemeParams] = useState(webApp?.themeParams ?? {});

  // The user can flip to night mode while the app is open; themeParams only
  // updates via this event, CSS vars are re-read by the browser automatically.
  useEffect(() => {
    if (!webApp) return;
    const handleThemeChanged = () => setThemeParams({ ...webApp.themeParams });
    webApp.onEvent('themeChanged', handleThemeChanged);
    return () => webApp.offEvent('themeChanged', handleThemeChanged);
  }, [webApp]);

  return { webApp, themeParams };
}
