// hooks/useMainButton.ts
import { useEffect } from 'react';
import { getTelegramWebApp } from './useTelegramWebApp';

interface MainButtonOptions {
  text: string;
  onClick: () => void;
  enabled?: boolean;
  visible?: boolean;
  progress?: boolean;
}

// "MainButton" is the Bot API name; some newer clients render it as the
// bottom-bar button, but the API below still targets the same control.
export function useMainButton({
  text,
  onClick,
  enabled = true,
  visible = true,
  progress = false,
}: MainButtonOptions) {
  const webApp = getTelegramWebApp();

  useEffect(() => {
    webApp?.MainButton.setText(text);
  }, [webApp, text]);

  useEffect(() => {
    if (!webApp) return;
    enabled ? webApp.MainButton.enable() : webApp.MainButton.disable();
  }, [webApp, enabled]);

  useEffect(() => {
    if (!webApp) return;
    visible ? webApp.MainButton.show() : webApp.MainButton.hide();
    return () => webApp.MainButton.hide();
  }, [webApp, visible]);

  useEffect(() => {
    if (!webApp) return;
    progress ? webApp.MainButton.showProgress(true) : webApp.MainButton.hideProgress();
  }, [webApp, progress]);

  useEffect(() => {
    if (!webApp) return;
    webApp.MainButton.onClick(onClick);
    return () => webApp.MainButton.offClick(onClick);
  }, [webApp, onClick]);
}
