import './CartSummary.css';

interface CartSummaryProps {
  items: CartItem[];
  subtotal: number;
  deliveryFee: number;
  total: number;
  currency: string;
  onIncrement: (id: string) => void;
  onDecrement: (id: string) => void;
  onRemove: (id: string) => void;
}

export function CartSummary({
  items,
  subtotal,
  deliveryFee,
  total,
  currency,
  onIncrement,
  onDecrement,
  onRemove,
}: CartSummaryProps) {
  if (items.length === 0) {
    return (
      <section className="cart-summary cart-summary--empty" aria-label="Cart">
        <p>Your cart is empty.</p>
      </section>
    );
  }

  return (
    <section className="cart-summary" aria-label="Order items">
      <ul className="cart-summary__list">
        {items.map((item) => (
          <li key={item.id} className="cart-summary__item">
            {item.imageUrl && (
              <img className="cart-summary__thumb" src={item.imageUrl} alt={item.name} />
            )}
            <div className="cart-summary__body">
              <div className="cart-summary__top-row">
                <div className="cart-summary__details">
                  <span className="cart-summary__name">{item.name}</span>
                  {item.variant && <span className="cart-summary__variant">{item.variant}</span>}
                  <span className="cart-summary__unit-price">
                    {formatPrice(item.unitPrice, currency)}
                  </span>
                </div>
                <span className="cart-summary__line-total">
                  {formatPrice(item.unitPrice * item.quantity, currency)}
                </span>
              </div>

              <div className="cart-summary__controls">
                <div
                  className="cart-summary__stepper"
                  role="group"
                  aria-label={`Quantity for ${item.name}`}
                >
                  <button
                    type="button"
                    className="cart-summary__stepper-btn"
                    onClick={() => onDecrement(item.id)}
                    disabled={item.quantity <= 1}
                    aria-label={`Decrease quantity of ${item.name}`}
                  >
                    −
                  </button>
                  <span className="cart-summary__quantity" aria-live="polite">
                    {item.quantity}
                  </span>
                  <button
                    type="button"
                    className="cart-summary__stepper-btn"
                    onClick={() => onIncrement(item.id)}
                    aria-label={`Increase quantity of ${item.name}`}
                  >
                    +
                  </button>
                </div>
                <button
                  type="button"
                  className="cart-summary__remove"
                  onClick={() => onRemove(item.id)}
                  aria-label={`Remove ${item.name} from cart`}
                >
                  Remove
                </button>
              </div>
            </div>
          </li>
        ))}
      </ul>

      <dl className="cart-summary__totals">
        <div className="cart-summary__totals-row">
          <dt>Subtotal</dt>
          <dd>{formatPrice(subtotal, currency)}</dd>
        </div>
        <div className="cart-summary__totals-row">
          <dt>Delivery</dt>
          <dd>{formatPrice(deliveryFee, currency)}</dd>
        </div>
        <div className="cart-summary__totals-row cart-summary__totals-row--total">
          <dt>Total</dt>
          <dd>{formatPrice(total, currency)}</dd>
        </div>
      </dl>
    </section>
  );
}
