      <Field
        id="city"
        label="City"
        value={value.city}
        error={errors.city}
        onChange={onChange}
        onBlur={onBlur}
        autoComplete="address-level2"
      />

      <div className="address-form__row">
        <Field
          id="street"
          label="Street"
          value={value.street}
          error={errors.street}
          onChange={onChange}
          onBlur={onBlur}
          autoComplete="address-line1"
          className="address-form__field--grow"
        />
        <Field
          id="house"
          label="House"
          value={value.house}
          error={errors.house}
          onChange={onChange}
          onBlur={onBlur}
          className="address-form__field--narrow"
        />
      </div>

      <div className="address-form__row">
        <Field
          id="apartment"
          label="Apartment (optional)"
