          onChange={onChange}
          onBlur={onBlur}
          className="address-form__field--narrow"
        />
        <Field
          id="postalCode"
          label="Postal code (optional)"
          value={value.postalCode}
          onChange={onChange}
          onBlur={onBlur}
          autoComplete="postal-code"
          className="address-form__field--narrow"
        />
      </div>

      <div className="address-form__field">
        <label className="address-form__label" htmlFor="comment">
          Comment for courier (optional)
        </label>
        <textarea
          id="comment"
          className="address-form__textarea"
