}

interface FieldProps {
  id: keyof DeliveryAddress;
  label: string;
  value: string;
  error?: string;
  type?: string;
  autoComplete?: string;
  className?: string;
  onChange: (field: keyof DeliveryAddress, value: string) => void;
  onBlur: (field: keyof DeliveryAddress) => void;
}

function Field({
  id,
  label,
  value,
  error,
  type = 'text',
  autoComplete,
  className,
  onChange,
  onBlur,
}: FieldProps) {
  return (
    <div className={`address-form__field ${className ?? ''}`.trim()}>
      <label className="address-form__label" htmlFor={id}>
        {label}
      </label>
      <input
        id={id}
        name={id}
        type={type}
        className={`address-form__input ${error ? 'address-form__input--invalid' : ''}`.trim()}
        value={value}
        autoComplete={autoComplete}
        onChange={(e) => onChange(id, e.target.value)}
        onBlur={() => onBlur(id)}
        aria-invalid={Boolean(error)}
        aria-describedby={error ? `${id}-error` : undefined}
      />
      {error && (
        <span className="address-form__error" id={`${id}-error`} role="alert">
          {error}
        </span>
      )}
    </div>
  );
}
