// components/CheckoutScreen.tsx
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { AddressErrors, CartItem, DeliveryAddress } from '../types';
import { formatPrice } from '../utils/formatPrice';
import { useTelegramWebApp } from '../hooks/useTelegramWebApp';
import { useBackButton } from '../hooks/useBackButton';
import { useMainButton } from '../hooks/useMainButton';
import { CartSummary } from './CartSummary';
import { AddressForm } from './AddressForm';
import './CheckoutScreen.css';

const DELIVERY_FEE = 500; // $5.00 in minor units
const CURRENCY = 'USD';

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  house: '',
  apartment: '',
  postalCode: '',
  comment: '',
};

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};
  if (!address.fullName.trim()) errors.fullName = 'Enter the recipient’s full name.';
  if (!/^\+?[0-9\s()-]{7,}$/.test(address.phone.trim())) errors.phone = 'Enter a valid phone number.';
  if (!address.city.trim()) errors.city = 'Enter a city.';
  if (!address.street.trim()) errors.street = 'Enter a street.';
  if (!address.house.trim()) errors.house = 'Enter a house/building number.';
  return errors;
}

interface CheckoutScreenProps {
  items: CartItem[];
  onBackToCart: () => void;
  onRemoveItem: (id: string) => void;
  onChangeQuantity: (id: string, quantity: number) => void;
  onPaid: (address: DeliveryAddress) => void;
}

export function CheckoutScreen({
  items,
  onBackToCart,
  onRemoveItem,
  onChangeQuantity,
  onPaid,
}: CheckoutScreenProps) {
  const { webApp } = useTelegramWebApp();
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isDirty, setIsDirty] = useState(false);
  const [isPaying, setIsPaying] = useState(false);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items]
  );
  const deliveryFee = items.length > 0 ? DELIVERY_FEE : 0;
  const total = subtotal + deliveryFee;

  const fieldErrors = useMemo(() => validateAddress(address), [address]);
  const visibleErrors = useMemo(() => {
    const result: AddressErrors = {};
    (Object.keys(fieldErrors) as (keyof DeliveryAddress)[]).forEach((key) => {
      if (touched[key]) result[key] = fieldErrors[key];
    });
    return result;
  }, [fieldErrors, touched]);
  const isValid = Object.keys(fieldErrors).length === 0 && items.length > 0;

  // One-time host setup: full height, frame colors matched to the page so
  // there's no seam, and no vertical swipe-to-close while the cart list scrolls.
  useEffect(() => {
    if (!webApp) return;
    webApp.ready();
    webApp.expand();

    const frameColor = webApp.themeParams.secondary_bg_color ?? webApp.themeParams.bg_color;
    if (frameColor) {
      webApp.setHeaderColor(frameColor);
      webApp.setBackgroundColor(frameColor);
      if (webApp.isVersionAtLeast('7.10')) {
        webApp.setBottomBarColor(frameColor);
      }
    }

    if (webApp.isVersionAtLeast('7.7')) {
      webApp.disableVerticalSwipes();
    }
    return () => {
      if (webApp.isVersionAtLeast('7.7')) {
        webApp.enableVerticalSwipes();
      }
    };
  }, [webApp]);

  // Don't let a swipe-down silently discard an order in progress.
  useEffect(() => {
    if (!webApp) return;
    if (isDirty && !isPaying) {
      webApp.enableClosingConfirmation();
    } else {
      webApp.disableClosingConfirmation();
    }
  }, [webApp, isDirty, isPaying]);

  const handleFieldChange = useCallback((field: keyof DeliveryAddress, value: string) => {
    setAddress((prev) => ({ ...prev, [field]: value }));
    setTouched((prev) => ({ ...prev, [field]: true }));
    setIsDirty(true);
  }, []);

  const handleFieldBlur = useCallback((field: keyof DeliveryAddress) => {
    setTouched((prev) => ({ ...prev, [field]: true }));
  }, []);

  const handleBack = useCallback(() => {
    if (!webApp || !isDirty || isPaying) {
      onBackToCart();
      return;
    }
    webApp.showConfirm('Discard this order and go back to the cart?', (confirmed) => {
      if (confirmed) {
        webApp.disableClosingConfirmation();
        onBackToCart();
      }
    });
  }, [webApp, isDirty, isPaying, onBackToCart]);

  useBackButton(handleBack, true);

  const handleIncrement = useCallback(
    (id: string) => {
      webApp?.HapticFeedback.selectionChanged();
      const item = items.find((i) => i.id === id);
      if (item) onChangeQuantity(id, item.quantity + 1);
      setIsDirty(true);
    },
    [webApp, items, onChangeQuantity]
  );

  const handleDecrement = useCallback(
    (id: string) => {
      webApp?.HapticFeedback.selectionChanged();
      const item = items.find((i) => i.id === id);
      if (item && item.quantity > 1) onChangeQuantity(id, item.quantity - 1);
      setIsDirty(true);
    },
    [webApp, items, onChangeQuantity]
  );

  const handleRemove = useCallback(
    (id: string) => {
      webApp?.HapticFeedback.impactOccurred('light');
      onRemoveItem(id);
      setIsDirty(true);
    },
    [webApp, onRemoveItem]
  );

  const handlePay = useCallback(() => {
    if (!isValid || isPaying) return;
    setIsPaying(true);
    webApp?.HapticFeedback.impactOccurred('light');
    if (webApp?.isVersionAtLeast('8.0')) {
      webApp.hideKeyboard();
    }

    // Replace with a real order/payment request to your backend.
    window.setTimeout(() => {
      setIsPaying(false);
      setIsDirty(false);
      webApp?.disableClosingConfirmation();
      webApp?.HapticFeedback.notificationOccurred('success');
      if (webApp) {
        webApp.showAlert('Payment successful! Your order is on its way.', () => onPaid(address));
      } else {
        onPaid(address);
      }
    }, 1200);
  }, [isValid, isPaying, webApp, address, onPaid]);

  useMainButton({
    text: isPaying ? 'Processing…' : `Pay ${formatPrice(total, CURRENCY)}`,
    onClick: handlePay,
    enabled: isValid && !isPaying,
    progress: isPaying,
  });

  return (
    <div className="checkout-screen">
      <header className="checkout-screen__header">
        <h1 className="checkout-screen__title">Checkout</h1>
      </header>

      <CartSummary
        items={items}
        subtotal={subtotal}
        deliveryFee={deliveryFee}
        total={total}
        currency={CURRENCY}
        onIncrement={handleIncrement}
        onDecrement={handleDecrement}
        onRemove={handleRemove}
      />

      <AddressForm
        value={address}
        errors={visibleErrors}
        onChange={handleFieldChange}
        onBlur={handleFieldBlur}
      />

      {/* Keeps the last field clear of Telegram's bottom-bar button */}
      <div className="checkout-screen__bottom-spacer" aria-hidden="true" />
    </div>
  );
}
