// App.tsx — minimal demo wiring (not part of the checkout screen itself)
import React, { useState } from 'react';
import { CheckoutScreen } from './components/CheckoutScreen';
import { CartItem, DeliveryAddress } from './types';

const SAMPLE_ITEMS: CartItem[] = [
  {
    id: '1',
    name: 'Wireless Headphones',
    variant: 'Black',
    unitPrice: 8990,
    quantity: 1,
    imageUrl: 'https://example.com/headphones.jpg',
  },
  { id: '2', name: 'USB-C Cable 2m', unitPrice: 1290, quantity: 2 },
];

type Screen = 'cart' | 'checkout';

export function App() {
  const [screen, setScreen] = useState<Screen>('checkout');
  const [items, setItems] = useState<CartItem[]>(SAMPLE_ITEMS);

  const handleChangeQuantity = (id: string, quantity: number) => {
    setItems((prev) => prev.map((item) => (item.id === id ? { ...item, quantity } : item)));
  };

  const handleRemoveItem = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
  };

  const handlePaid = (address: DeliveryAddress) => {
    console.log('Order paid, deliver to:', address);
    setScreen('cart');
  };

  if (screen === 'cart') {
    // The cart screen itself is out of scope here — this is where
    // onBackToCart lands.
    return <div>Cart screen goes here.</div>;
  }

  return (
    <CheckoutScreen
      items={items}
      onBackToCart={() => setScreen('cart')}
      onRemoveItem={handleRemoveItem}
      onChangeQuantity={handleChangeQuantity}
      onPaid={handlePaid}
    />
  );
}
